  {
    "block_id": "Wu6VdZobVoCmFcxlIsWcZeYwnAz",
    "block_type": 2,
    "parent_id": "KKqHd8oADoL3PRxzsrecHtUWnBK",
    "text": {
      "elements": [
        {
          "text_run": {
            "content": "Gemini-S1 是一款集高性能计算、丰富交互方式、多模联网能力于一体的智能硬件开发平台，专为物联网开发者、创客、教育机构和智能家居爱好者设计。它集高性能内核、直观交互、智能语音、多模联网于一体，并原生搭载开放的  openvela 系统，为创客、学生、开发者提供从硬件到软件的一站式智能硬件开发平台。",
            "text_element_style": {
              "bold": false,
              "inline_code": false,
              "italic": false,
              "strikethrough": false,
              "underline": false
